#include "main.h"
#include "creature_bestiary.h"
#include <algorithm>
#include <cctype>

std::unordered_map<std::string, CreatureBestiaryInfo> CreatureBestiary::s_database;
bool CreatureBestiary::s_initialized = false;

static std::string to_lower(std::string s) {
	std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) { return (char)std::tolower(c); });
	return s;
}

std::string CreatureBestiary::GetClassName(CreatureBestiaryClass cid) {
	switch (cid) {
		case BESTIARY_AMPHIBIANS: return "Amphibians";
		case BESTIARY_AQUATIC: return "Aquatic";
		case BESTIARY_BIRDS: return "Birds";
		case BESTIARY_CONSTRUCTS: return "Constructs";
		case BESTIARY_DEMONS: return "Demons";
		case BESTIARY_DRAGONS: return "Dragons";
		case BESTIARY_ELEMENTALS: return "Elementals";
		case BESTIARY_EXTRA_DIMENSIONAL: return "Extra Dimensional";
		case BESTIARY_FEY: return "Fey";
		case BESTIARY_GIANTS: return "Giants";
		case BESTIARY_HUMANOIDS: return "Humanoids";
		case BESTIARY_HUMANS: return "Humans";
		case BESTIARY_MAGICAL_CREATURES: return "Magical Creatures";
		case BESTIARY_MAMMALS: return "Mammals";
		case BESTIARY_PLANTS: return "Plants";
		case BESTIARY_REPTILES: return "Reptiles";
		case BESTIARY_UNDEAD: return "Undead";
		case BESTIARY_BOSSES: return "Bosses";
		case BESTIARY_NPCS: return "NPCs";
		case BESTIARY_OTHERS: default: return "Others";
	}
}

std::vector<std::string> CreatureBestiary::GetAllClassNames() {
	std::vector<std::string> list;
	for (int i = 0; i < (int)BESTIARY_CLASS_COUNT; ++i) {
		list.push_back(GetClassName((CreatureBestiaryClass)i));
	}
	return list;
}

std::string CreatureBestiary::GetTierName(CreatureDifficultyTier tier) {
	switch (tier) {
		case TIER_HARMLESS: return "Harmless";
		case TIER_TRIVIAL: return "Trivial";
		case TIER_EASY: return "Easy";
		case TIER_MEDIUM: return "Medium";
		case TIER_HARD: return "Hard";
		case TIER_CHALLENGING: return "Challenging";
		default: return "Easy";
	}
}

CreatureDifficultyTier CreatureBestiary::EstimateDifficulty(int hp, int exp) {
	if (exp <= 0 || (hp <= 35 && exp <= 1)) return TIER_HARMLESS;
	if (hp <= 95 && exp <= 40) return TIER_TRIVIAL;
	if (hp <= 500 && exp <= 300) return TIER_EASY;
	if (hp <= 3500 && exp <= 2400) return TIER_MEDIUM;
	if (hp <= 22000 && exp <= 13000) return TIER_HARD;
	return TIER_CHALLENGING;
}

std::string CreatureBestiary::GetWikiUrl(const std::string& name) {
	std::string clean = name;
	for (char& c : clean) { if (c == ' ') c = '_'; }
	return "https://tibia.fandom.com/wiki/" + clean;
}

void CreatureBestiary::AddEntry(const std::string& name, CreatureBestiaryClass cid, int hp, int exp, int speed, int armor, int def,
                                const std::string& elem, const std::string& weak, const std::string& desc) {
	CreatureBestiaryInfo info;
	info.name = name;
	info.class_id = cid;
	info.bestiary_class = GetClassName(cid);
	info.health = hp;
	info.experience = exp;
	info.ratio = (hp > 0) ? ((double)exp / (double)hp) : 0.0;
	info.speed = speed;
	info.armor = armor;
	info.defense = def;
	info.tier = EstimateDifficulty(hp, exp);
	info.tier_name = GetTierName(info.tier);
	info.wiki_url = GetWikiUrl(name);
	info.elements = elem;
	info.weaknesses = weak;
	info.description = desc;
	s_database[to_lower(name)] = info;
}

