const CreatureBestiaryInfo* CreatureBestiary::GetInfo(const std::string& name) {
	Initialize();
	auto it = s_database.find(to_lower(name));
	if (it != s_database.end()) {
		return &(it->second);
	}
	return nullptr;
}

CreatureBestiaryClass CreatureBestiary::GetClassForCreature(const std::string& name, bool isNpc) {
	if (isNpc) return BESTIARY_NPCS;
	Initialize();
	auto it = s_database.find(to_lower(name));
	if (it != s_database.end()) {
		return it->second.class_id;
	}
	return BESTIARY_OTHERS;
}
